def big_omega(n):
    total = 0
    d = 2
    while d * d <= n:
        while n % d == 0:
            total += 1
            n //= d
        d += 1
    if n > 1:
        total += 1
    return total

def chain_defect(seq):
    n = len(seq)
    for i in range(n):
        if all(seq[j] == seq[i] for j in range(i, n)):
            return i
    return None

from math import factorial
from functools import reduce

def count_maximal_chains(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = 1
    omega = sum(factors.values())
    return factorial(omega) // reduce(lambda x,y: x*y, (factorial(e) for e in factors.values()), 1)
